import { HB_ROMAN } from '../../core';
import { FEATURES } from '../../config';
import { daysBetween, localDate } from '../../data/db';
import { useApp } from '../../data/store';
import { changeDir, changeSummary, versionChange } from '../../rehab/findings';
import { PHASE_LABEL, buildPlan } from '../../rehab/planner';
import { FindingsToExercises } from '../components/findings';
import { PhaseGoals } from '../components/PhaseGoals';
import { HomeKeepSafe } from '../components/KeepSafe';
import { AppBar, EstBadge, Notice, RegionMeters } from '../components/common';
import { LineChart } from '../components/LineChart';
import { Icon } from '../icons';
import { SIDE_LABEL, dayLabel, fmtDate } from '../labels';
import { caseById } from '../../cases/library';
import { PhotoMeasure, StillTrend, trendSummary } from '../components/photo';
import { ROLE_LABEL, roleOf, showClinicalTools, showScales } from '../role';

interface TodayTask {
  id: 'assess' | 'rehab';
  done: boolean;
  icon: string;
  href: string;
  title: string;
  sub: string;
  cta: string;
}

export function Home() {
  const { profile, sessions, rehab, photos } = useApp();
  const scales = showScales(profile);
  const clinical = showClinicalTools(profile);
  if (!profile) return null;
  const days = daysBetween(profile.onsetDate);
  const scored = sessions.filter((s) => s.analysis.scores);
  const latest = scored[scored.length - 1];
  const prev = scored[scored.length - 2];
  const plan = buildPlan({ daysSinceOnset: days, latest: FEATURES.rehab === 'personalized' ? (latest?.analysis ?? null) : null });
  const today = localDate();
  const doneToday = new Set(rehab.filter((r) => r.date === today).map((r) => r.exerciseId));
  const planDone = plan.items.filter((i) => doneToday.has(i.exercise.id)).length;
  const lastAt = sessions[sessions.length - 1]?.createdAt;
  const sinceLast = lastAt ? daysBetween(localDate(new Date(lastAt))) : null;
  const due = sinceLast === null || sinceLast >= 7;
  const demoCase = profile.demoCaseId ? caseById(profile.demoCaseId) : undefined;
  const caseRecords = demoCase ? photos.filter((p) => p.caseId === demoCase.id) : [];
  const lastPhoto = [...caseRecords].reverse().find((p) => p.analysis && p.expression !== 'rest');
  const photoTrend = trendSummary(caseRecords);

  // Today's to-do: one card with the next step as its button, everything else further down (decision guide §5 #1).
  // In the acute phase exercises come first (eye care and gentle massage before measuring); otherwise a due weekly
  // assessment comes first.
  const rehabLeft = plan.items.length - planDone;
  const tasks: TodayTask[] = [
    {
      id: 'assess',
      done: !due,
      icon: 'camera',
      href: '#/assess',
      title: '얼굴 평가',
      sub:
        sinceLast === null
          ? '13가지 표정을 약 2분 촬영(빠른 평가는 6가지·1분). 이후 평가와 비교해 회복 경과를 봅니다.'
          : due
            ? `마지막 평가 ${sinceLast}일 전 · 1주일에 한 번, 같은 장소와 조명에서`
            : `${sinceLast === 0 ? '오늘' : `${sinceLast}일 전`} 평가함 · 다음 평가는 ${7 - sinceLast}일 뒤`,
      cta: sinceLast === null ? '첫 평가 시작' : '얼굴 평가하기',
    },
  ];
  if (FEATURES.rehab !== 'off' && plan.items.length > 0) {
    const rehabTask: TodayTask = {
      id: 'rehab',
      done: rehabLeft === 0,
      icon: 'activity',
      href: rehabLeft ? `#/routine/${Math.max(0, plan.items.findIndex((i) => !doneToday.has(i.exercise.id)))}` : '#/rehab',
      title: `재활 루틴 · ${planDone} / ${plan.items.length} 완료`,
      sub: plan.phaseReason,
      cta: `${planDone ? '오늘 루틴 이어서 하기' : '오늘 루틴 시작'} (${rehabLeft}가지 남음)`,
    };
    if (plan.phase === 'acute') tasks.unshift(rehabTask);
    else tasks.push(rehabTask);
  }
  const next = tasks.find((t) => !t.done);

  return (
    <>
      <AppBar
        title={demoCase ? demoCase.title : profile.nickname ? `${profile.nickname}님` : '안녕하세요'}
        sub={`${dayLabel(days)} · ${PHASE_LABEL[plan.phase]} · 마비 쪽 ${SIDE_LABEL[profile.affectedSide]}`}
      />
      <main class="main">
        {demoCase && lastPhoto && (
          <div class="card">
            <div class="card-head">
              <span class="ink2 small">사진 경과 · 공개 사례</span>
              <a class="btn sm ghost" href={`#/case/${demoCase.id}`}>
                자세히 <Icon name="chev" />
              </a>
            </div>
            <div class="row" style={{ alignItems: 'stretch' }}>
              <div style={{ width: '44%', flex: 'none' }}>
                <PhotoMeasure record={lastPhoto} />
              </div>
              <div class="stack grow" style={{ gap: '6px' }}>
                <b>{lastPhoto.label}</b>
                {photoTrend.map((t) => (
                  <div class="tile">
                    <span class="label">{t.label} 좌우 차이</span>
                    <span class="value tabular" style={{ fontSize: '20px' }}>
                      {t.first.mm.toFixed(1)}→{t.last.mm.toFixed(1)}
                      <small>mm</small>
                    </span>
                    <span class="xsmall muted">
                      {t.first.day}일째 → {t.last.day}일째
                    </span>
                  </div>
                ))}
              </div>
            </div>
            <StillTrend records={caseRecords} height={160} />
            <p class="xsmall muted">Andrea Kamphuis 공개 사진(CC BY-SA 4.0)을 앱이 분석한 예시값입니다. 진료 기록이 아닙니다.</p>
          </div>
        )}

        <div class="card accent">
          <div class="card-head">
            <h3>오늘 할 일</h3>
            <span class="chip accent tabular">
              {tasks.filter((t) => t.done).length} / {tasks.length} 완료
            </span>
          </div>
          <div class="list">
            {tasks.map((t) => (
              <a class="list-item" href={t.href}>
                <Icon name={t.done ? 'check' : t.icon} />
                <div class="grow">
                  {t.done ? <span class="ink2">{t.title}</span> : <b>{t.title}</b>}
                  <div class="xsmall muted">{t.sub}</div>
                </div>
                <Icon name="chev" class="chev" />
              </a>
            ))}
          </div>
          {next ? (
            <a class="btn primary block" href={next.href}>
              <Icon name={next.id === 'rehab' ? 'play' : 'camera'} /> {next.cta}
            </a>
          ) : (
            <p class="small ink2" style={{ margin: 0 }}>
              오늘 할 일을 모두 마쳤어요.
            </p>
          )}
        </div>

        {latest?.analysis.scores && (
          <div class="card">
            <div class="card-head">
              <span class="ink2 small">최근 평가 · {fmtDate(latest.createdAt)}</span>
              <a class="btn sm ghost" href={`#/session/${latest.id}`}>
                자세히 <Icon name="chev" />
              </a>
            </div>
            <div class="row between">
              <div>
                <div class="small ink2">마비 쪽 움직임 (건강한 쪽 = 100%)</div>
                <span class="hero-num">{latest.analysis.scores.functionIndex}</span>
                <span class="hero-unit">%</span>
              </div>
              <div class="stack" style={{ alignItems: 'flex-end', gap: '4px' }}>
                {scales && (
                  <>
                    <span class="chip">
                      Sunnybrook {latest.analysis.scores.composite} <EstBadge />
                    </span>
                    <span class="chip">
                      HB {HB_ROMAN[latest.analysis.scores.houseBrackmann.grade]} <EstBadge />
                    </span>
                  </>
                )}
                {prev?.analysis.scores && (
                  <span class="chip accent">
                    {changeDir(latest.analysis.scores.functionIndex - prev.analysis.scores.functionIndex) === 'same' ? '변화 없음 · ' : ''}
                    이전 대비 {latest.analysis.scores.functionIndex - prev.analysis.scores.functionIndex >= 0 ? '+' : ''}
                    {latest.analysis.scores.functionIndex - prev.analysis.scores.functionIndex}%p
                  </span>
                )}
              </div>
            </div>
            {prev?.analysis.scores && (
              <p class="small" style={{ margin: 0 }}>
                <b>{changeSummary(latest.analysis, prev.analysis, latest.daysSinceOnset - prev.daysSinceOnset)}</b>
              </p>
            )}
            {prev?.analysis.scores && versionChange(latest.analysis, prev.analysis) && (
              <p class="xsmall muted" style={{ margin: 0 }}>
                {versionChange(latest.analysis, prev.analysis)}
              </p>
            )}
            <RegionMeters regional={latest.analysis.scores.regional} />
            {scored.length >= 2 && (
              <LineChart
                ariaLabel="마비 쪽 움직임 (건강한 쪽 = 100%) 추이"
                series={[
                  {
                    id: 'ffi',
                    label: '움직임 %',
                    color: 'var(--series-1)',
                    points: scored.map((s) => ({ x: s.daysSinceOnset, y: s.analysis.scores!.functionIndex })),
                  },
                ]}
                yMax={100}
                yTicks={[0, 50, 100]}
                ySuffix="%"
                xLabel={(x) => `${x}일`}
                xTitle="발병 후 일수"
                height={150}
              />
            )}
          </div>
        )}

        <a class="btn ghost block" href="#/upload">
          <Icon name="upload" /> 이미 찍은 사진·영상으로 평가
        </a>
        <a class="btn ghost block" href="#/synk">
          <Icon name="face" /> 연합운동만 따로 찾기 (10가지 표정)
        </a>
        {latest && (
          <a class="btn ghost block" href="#/report">
            <Icon name="clipboard" /> 진료 때 보여 주기 (의료진용 요약 한 장)
          </a>
        )}
        {clinical && (
          <div class="card tight">
            <div class="card-head">
              <span class="ink2 small">진료·연구 ({ROLE_LABEL[roleOf(profile)]} 모드)</span>
            </div>
            <div class="list">
              {latest && (
                <a class="list-item" href={`#/rate/${latest.id}`}>
                  <Icon name="clipboard" />
                  <div class="grow">
                    최근 평가에 임상가 평가 입력
                    <div class="xsmall muted">HB·Sunnybrook 항목 · 저장 전까지 앱 추정값 가림</div>
                  </div>
                  <Icon name="chev" class="chev" />
                </a>
              )}
              <a class="list-item" href="#/subjects">
                <Icon name="face" />
                <div class="grow">연구 피험자 (가명 코드 전환)</div>
                <Icon name="chev" class="chev" />
              </a>
              <a class="list-item" href="#/research">
                <Icon name="flask" />
                <div class="grow">연구 도구 (일치도·검수)</div>
                <Icon name="chev" class="chev" />
              </a>
            </div>
          </div>
        )}
        <PhaseGoals plan={plan} />

        <HomeKeepSafe />

        {FEATURES.rehab === 'personalized' && latest?.analysis.scores && (
          <div class="card">
            <div class="card-head">
              <h3>지금 필요한 움직임</h3>
              <span class="xsmall muted">약한 부위부터</span>
            </div>
            <FindingsToExercises analysis={latest.analysis} plan={plan} />
          </div>
        )}

        {FEATURES.rehab !== 'off' &&
          plan.notices.slice(0, 1).map((n) => (
            <div class="card warn tight">
              <Notice tone="warn">
                <span class="small">{n}</span>
              </Notice>
            </div>
          ))}

        {FEATURES.demo && !demoCase && (
          <a class="card case-card" href="#/cases">
            <img src="cases/kamphuis/day19-expression.jpg" alt="" loading="lazy" />
            <div class="stack" style={{ gap: '4px' }}>
              <h3>실제 사진으로 보는 경과</h3>
              <p class="small ink2">공개된 벨마비 환자 사진을 이 앱이 분석해 1~19일 변화를 보여 줍니다.</p>
            </div>
          </a>
        )}

        <div class="card tight">
          <Notice tone="danger">
            <span class="small">
              <b>팔·다리 마비, 말이 어눌함, 심한 두통</b>이 함께 있거나 증상이 갑자기 나빠지면 즉시 <a href="tel:119">119</a>에 연락하세요.
            </span>
          </Notice>
        </div>
        <p class="xsmall muted center">연구용 프로토타입 · 진단 목적이 아닙니다</p>
      </main>
    </>
  );
}
