/**
 * Research package (SRS-DAT-014): what a study subject agreed to give (consent.ts), encrypted with the study
 * password, for the hospital research PC (moved by USB cable, never by messenger or e-mail). No name or nickname;
 * photos only with photo consent; sealed records keep their seals so the PC can check them again.
 *
 * File (JSON): { format, header, kdf, cipher, data }. The header (subject code, export time, consent, counts) is
 * readable without the password so the PC can list files, and it is bound to the ciphertext as AES-GCM additional
 * data: a changed header fails to open like a changed byte of the data. Key: PBKDF2-SHA-256 (PACKAGE_KDF_ROUNDS,
 * random salt) → AES-GCM 256 (random IV). The password is never stored; a device may keep its salted hash to catch
 * typos (SRS-SEC-006).
 */
import { canGiveResearchData, researchConsentOf, type ResearchConsent } from './consent';
import { canonicalJson, sha256Hex } from './integrity';
import { checkSecret, hashSecret } from './lock';
import { APP_INFO } from './records';
import type { RejectionRecord } from './rejections';
import type { AppState } from './store';
import type { ClinicianRating, Profile, RehabLog, SessionRecord, SessionSnapshots, SynkRecord } from './types';

export const PACKAGE_FORMAT = 'fpc-research/1';
export const PACKAGE_KDF_ROUNDS = 600_000;
export const STUDY_PASSWORD_MIN = 10;
/** Files with fewer rounds are not opened (a doctored header could otherwise ask for a weak key). */
const MIN_ROUNDS = 100_000;
const MAX_ROUNDS = 10_000_000;

export interface PackageCounts {
  sessions: number;
  ratings: number;
  rehab: number;
  synk: number;
  rejections: number;
  photos: number;
}

export interface PackageHeader {
  format: typeof PACKAGE_FORMAT;
  /** Pseudonymous study code: the research subject's, or the one typed for own records (the app always gives one). */
  subjectCode: string | null;
  exportedAt: string;
  app: { version: string; build: string };
  /** The decision in force when the file was made. */
  consent: { version: string; at: string; items: ResearchConsent['items'] };
  counts: PackageCounts;
}

export interface PackagePhoto {
  sessionId: string;
  step: string;
  w: number;
  h: number;
  /** SHA-256 of the JPEG bytes, checked on the PC. */
  sha256: string;
  /** JPEG, base64. */
  jpeg: string;
}

export interface PackageContent {
  subject: Pick<Profile, 'affectedSide' | 'onsetDate' | 'etiology' | 'birthYear'>;
  /** Every recorded decision, oldest first (the header carries the one in force). */
  consentHistory: ResearchConsent[];
  sessions: (SessionRecord & { integrityVerified: boolean })[];
  clinicianRatings: ClinicianRating[];
  rehabLogs: RehabLog[];
  synkinesisFinder: (SynkRecord & { integrityVerified: boolean })[];
  rejections: RejectionRecord[];
  photos: PackagePhoto[];
}

export interface PackageFile {
  format: typeof PACKAGE_FORMAT;
  header: PackageHeader;
  kdf: { name: 'PBKDF2'; hash: 'SHA-256'; rounds: number; salt: string };
  cipher: { name: 'AES-GCM'; iv: string };
  data: string;
}

const b64 = (bytes: ArrayBuffer | Uint8Array): string => {
  const u = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let s = '';
  for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode(...u.subarray(i, i + 0x8000));
  return btoa(s);
};
const unb64 = (s: string): Uint8Array => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

/**
 * What goes into the package of the open records, as the consent in force allows (throws without it). `snapshots`
 * = the stored assessment photos; they go in only with photo consent, and only for sessions in the records.
 */
export async function buildPackage(
  s: Pick<AppState, 'profile' | 'sessions' | 'integrity' | 'ratings' | 'rehab' | 'synk' | 'rejections'>,
  snapshots: readonly SessionSnapshots[],
  subjectCode: string | null,
  now: Date = new Date(),
): Promise<{ header: PackageHeader; content: PackageContent }> {
  const p = s.profile;
  const consent = researchConsentOf(p);
  if (!p || !consent || !canGiveResearchData(consent)) throw new Error('NO_RESEARCH_CONSENT');
  const ids = new Set(s.sessions.map((x) => x.id));
  const photos: PackagePhoto[] = [];
  if (consent.items.photos) {
    for (const snap of snapshots) {
      if (!ids.has(snap.id)) continue;
      for (const [step, item] of Object.entries(snap.items)) {
        if (!item) continue;
        const bytes = new Uint8Array(await item.blob.arrayBuffer());
        photos.push({ sessionId: snap.id, step, w: item.w, h: item.h, sha256: await sha256Hex(bytes), jpeg: b64(bytes) });
      }
    }
  }
  const content: PackageContent = {
    // Direct identifiers (nickname, profile id) never go in.
    subject: { affectedSide: p.affectedSide, onsetDate: p.onsetDate, etiology: p.etiology, birthYear: p.birthYear },
    consentHistory: p.research ?? [consent],
    sessions: s.sessions.map((x) => ({ ...x, integrityVerified: s.integrity[x.id] ?? false })),
    clinicianRatings: s.ratings,
    rehabLogs: s.rehab,
    synkinesisFinder: s.synk.map((x) => ({ ...x, integrityVerified: s.integrity[x.id] ?? false })),
    rejections: s.rejections,
    photos,
  };
  const header: PackageHeader = {
    format: PACKAGE_FORMAT,
    subjectCode,
    exportedAt: now.toISOString(),
    app: { ...APP_INFO },
    consent: { version: consent.version, at: consent.at, items: consent.items },
    counts: {
      sessions: content.sessions.length,
      ratings: content.clinicianRatings.length,
      rehab: content.rehabLogs.length,
      synk: content.synkinesisFinder.length,
      rejections: content.rejections.length,
      photos: photos.length,
    },
  };
  return { header, content };
}

async function keyFrom(password: string, salt: Uint8Array, rounds: number): Promise<CryptoKey> {
  const base = await crypto.subtle.importKey('raw', new TextEncoder().encode(password.normalize('NFC')), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', hash: 'SHA-256', salt: salt as BufferSource, iterations: rounds },
    base,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

const aad = (h: PackageHeader): Uint8Array => new TextEncoder().encode(canonicalJson(h));

/** Encrypts a built package with the study password. `rounds` is for tests only. */
export async function sealPackage(
  pkg: { header: PackageHeader; content: PackageContent },
  password: string,
  rounds: number = PACKAGE_KDF_ROUNDS,
): Promise<PackageFile> {
  if (password.length < STUDY_PASSWORD_MIN) throw new Error('STUDY_PASSWORD_SHORT');
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await keyFrom(password, salt, rounds);
  const plain = new TextEncoder().encode(JSON.stringify(pkg.content));
  const data = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv: iv as BufferSource, additionalData: aad(pkg.header) as BufferSource },
    key,
    plain as BufferSource,
  );
  return {
    format: PACKAGE_FORMAT,
    header: pkg.header,
    kdf: { name: 'PBKDF2', hash: 'SHA-256', rounds, salt: b64(salt) },
    cipher: { name: 'AES-GCM', iv: b64(iv) },
    data: b64(data),
  };
}

/** Opens a package (the PC collect tool, and the self-check after making one). Throws on a wrong password or any change. */
export async function openPackage(file: PackageFile, password: string): Promise<{ header: PackageHeader; content: PackageContent }> {
  if (file?.format !== PACKAGE_FORMAT || file.kdf?.name !== 'PBKDF2' || file.cipher?.name !== 'AES-GCM') throw new Error('NOT_A_PACKAGE');
  const rounds = file.kdf.rounds;
  if (!Number.isInteger(rounds) || rounds < MIN_ROUNDS || rounds > MAX_ROUNDS) throw new Error('NOT_A_PACKAGE');
  const key = await keyFrom(password, unb64(file.kdf.salt), rounds);
  let plain: ArrayBuffer;
  try {
    plain = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: unb64(file.cipher.iv) as BufferSource, additionalData: aad(file.header) as BufferSource },
      key,
      unb64(file.data) as BufferSource,
    );
  } catch {
    throw new Error('WRONG_PASSWORD_OR_CHANGED');
  }
  return { header: file.header, content: JSON.parse(new TextDecoder().decode(plain)) as PackageContent };
}

/** `KHU-001_2026-10-02_1530.fpcr.json` (own records: `own_…`). */
export function packageFileName(subjectCode: string | null, at: Date = new Date()): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  const day = `${at.getFullYear()}-${pad(at.getMonth() + 1)}-${pad(at.getDate())}`;
  return `${subjectCode ?? 'own'}_${day}_${pad(at.getHours())}${pad(at.getMinutes())}.fpcr.json`;
}

// ── Study password check on this device (optional) ───────────────────────

const STUDY_KEY = 'fpc.studypw.v1';

export function hasStudyPassword(): boolean {
  try {
    return !!localStorage.getItem(STUDY_KEY);
  } catch {
    return false;
  }
}

/** Keeps only a salted hash (as many rounds as the package key), to catch typos before a file is made. */
export async function setStudyPassword(password: string): Promise<void> {
  if (password.length < STUDY_PASSWORD_MIN) throw new Error('STUDY_PASSWORD_SHORT');
  localStorage.setItem(STUDY_KEY, JSON.stringify(await hashSecret(password.normalize('NFC'), PACKAGE_KDF_ROUNDS)));
}

export async function checkStudyPassword(password: string): Promise<boolean> {
  try {
    const v = localStorage.getItem(STUDY_KEY);
    return v ? await checkSecret(password.normalize('NFC'), JSON.parse(v)) : false;
  } catch {
    return false;
  }
}

export function clearStudyPassword(): void {
  try {
    localStorage.removeItem(STUDY_KEY);
  } catch {
    /* private mode */
  }
}
