/**
 * Pose-normalised landmarks (experiment; tools/eval methods 'trk3d' / 'app3d', not used by the app yet).
 *
 * The measures (measures.ts) read movement in the image plane, so a head turned a few degrees foreshortens the side
 * turned away more than the other and the ratio drifts (docs/04 §8, tools/blender/BENCH.md head conditions). Here the
 * landmarks are taken in 3D (x, y in pixels, z = the landmarker's depth, on the x pixel scale):
 *  1. every frame is fitted to the rest frame with a 3D similarity (Horn) on the rigid alignment candidates, least
 *     trimmed like the 2D fit (analyze.ts alignTo), so a turn or nod between rest and expression is undone in depth;
 *  2. rest and frames are then turned together about the vertical axis until the rest face is square to the camera
 *     (yaw from the depth difference of the symmetric anchor pairs). Pitch is left: it shortens both sides alike.
 * The result is written back as normalised x, y (z kept) in the rest image's frame, so the unchanged 2D analysis
 * runs on it. Tracked frames keep the detection's depth for their points (vision/track.ts), which is enough here: depth
 * enters only through the small rotation.
 */
import { ALIGNMENT_CANDIDATES, ALIGNMENT_KEEP } from './landmarks';
import type { FrameObservation } from './types';

export interface Vec3 {
  x: number;
  y: number;
  z: number;
}

/** Candidate pairs mirrored across the midline (patient right, patient left). */
const SYMMETRIC_PAIRS: readonly (readonly [number, number])[] = [
  [133, 362],
  [127, 356],
  [162, 389],
  [108, 337],
  [67, 297],
  [109, 338],
];

export const to3d = (obs: FrameObservation): Vec3[] => {
  const lm = obs.landmarks;
  const n = Math.floor(lm.length / 3);
  return Array.from({ length: n }, (_, i) => ({ x: lm[3 * i]! * obs.width, y: lm[3 * i + 1]! * obs.height, z: lm[3 * i + 2]! * obs.width }));
};

interface Similarity3 {
  s: number;
  /** Row-major 3×3 rotation. */
  R: number[];
  t: Vec3;
}

const apply3 = (T: Similarity3, p: Vec3): Vec3 => ({
  x: T.s * (T.R[0]! * p.x + T.R[1]! * p.y + T.R[2]! * p.z) + T.t.x,
  y: T.s * (T.R[3]! * p.x + T.R[4]! * p.y + T.R[5]! * p.z) + T.t.y,
  z: T.s * (T.R[6]! * p.x + T.R[7]! * p.y + T.R[8]! * p.z) + T.t.z,
});

const centroid3 = (ps: readonly Vec3[]): Vec3 => {
  const c = { x: 0, y: 0, z: 0 };
  for (const p of ps) {
    c.x += p.x / ps.length;
    c.y += p.y / ps.length;
    c.z += p.z / ps.length;
  }
  return c;
};

/** Eigenvector of the largest eigenvalue of a symmetric 4×4 matrix (cyclic Jacobi). */
function topEigenvector4(A: number[][]): number[] {
  const a = A.map((r) => [...r]);
  const V: number[][] = [0, 1, 2, 3].map((i) => [0, 1, 2, 3].map((j) => (i === j ? 1 : 0)));
  for (let sweep = 0; sweep < 50; sweep++) {
    let off = 0;
    for (let p = 0; p < 4; p++) for (let q = p + 1; q < 4; q++) off += a[p]![q]! ** 2;
    if (off < 1e-18) break;
    for (let p = 0; p < 4; p++)
      for (let q = p + 1; q < 4; q++) {
        if (Math.abs(a[p]![q]!) < 1e-15) continue;
        const theta = (a[q]![q]! - a[p]![p]!) / (2 * a[p]![q]!);
        const t = Math.sign(theta || 1) / (Math.abs(theta) + Math.sqrt(theta * theta + 1));
        const c = 1 / Math.sqrt(t * t + 1);
        const s = t * c;
        for (let k = 0; k < 4; k++) {
          const akp = a[k]![p]!;
          const akq = a[k]![q]!;
          a[k]![p] = c * akp - s * akq;
          a[k]![q] = s * akp + c * akq;
        }
        for (let k = 0; k < 4; k++) {
          const apk = a[p]![k]!;
          const aqk = a[q]![k]!;
          a[p]![k] = c * apk - s * aqk;
          a[q]![k] = s * apk + c * aqk;
        }
        for (let k = 0; k < 4; k++) {
          const vkp = V[k]![p]!;
          const vkq = V[k]![q]!;
          V[k]![p] = c * vkp - s * vkq;
          V[k]![q] = s * vkp + c * vkq;
        }
      }
  }
  let best = 0;
  for (let i = 1; i < 4; i++) if (a[i]![i]! > a[best]![best]!) best = i;
  return V.map((r) => r[best]!);
}

/** Least-squares similarity src → dst in 3D (Horn 1987, unit quaternion). */
export function fitSimilarity3(src: readonly Vec3[], dst: readonly Vec3[]): Similarity3 {
  const ca = centroid3(src);
  const cb = centroid3(dst);
  let Sxx = 0, Sxy = 0, Sxz = 0, Syx = 0, Syy = 0, Syz = 0, Szx = 0, Szy = 0, Szz = 0, ss = 0; // prettier-ignore
  for (let i = 0; i < src.length; i++) {
    const a = { x: src[i]!.x - ca.x, y: src[i]!.y - ca.y, z: src[i]!.z - ca.z };
    const b = { x: dst[i]!.x - cb.x, y: dst[i]!.y - cb.y, z: dst[i]!.z - cb.z };
    Sxx += a.x * b.x; Sxy += a.x * b.y; Sxz += a.x * b.z; // prettier-ignore
    Syx += a.y * b.x; Syy += a.y * b.y; Syz += a.y * b.z; // prettier-ignore
    Szx += a.z * b.x; Szy += a.z * b.y; Szz += a.z * b.z; // prettier-ignore
    ss += a.x * a.x + a.y * a.y + a.z * a.z;
  }
  const N = [
    [Sxx + Syy + Szz, Syz - Szy, Szx - Sxz, Sxy - Syx],
    [Syz - Szy, Sxx - Syy - Szz, Sxy + Syx, Szx + Sxz],
    [Szx - Sxz, Sxy + Syx, -Sxx + Syy - Szz, Syz + Szy],
    [Sxy - Syx, Szx + Sxz, Syz + Szy, -Sxx - Syy + Szz],
  ];
  const [w, x, y, z] = topEigenvector4(N) as [number, number, number, number];
  const R = [
    w * w + x * x - y * y - z * z, 2 * (x * y - w * z), 2 * (x * z + w * y),
    2 * (x * y + w * z), w * w - x * x + y * y - z * z, 2 * (y * z - w * x),
    2 * (x * z - w * y), 2 * (y * z + w * x), w * w - x * x - y * y + z * z,
  ]; // prettier-ignore
  let num = 0;
  for (let i = 0; i < src.length; i++) {
    const a = { x: src[i]!.x - ca.x, y: src[i]!.y - ca.y, z: src[i]!.z - ca.z };
    const b = { x: dst[i]!.x - cb.x, y: dst[i]!.y - cb.y, z: dst[i]!.z - cb.z };
    const ra = apply3({ s: 1, R, t: { x: 0, y: 0, z: 0 } }, a);
    num += ra.x * b.x + ra.y * b.y + ra.z * b.z;
  }
  const s = ss > 0 ? num / ss : 1;
  const rc = apply3({ s, R, t: { x: 0, y: 0, z: 0 } }, ca);
  return { s, R, t: { x: cb.x - rc.x, y: cb.y - rc.y, z: cb.z - rc.z } };
}

/** 3D version of analyze.ts alignTo: least-trimmed similarity of `pts` onto `ref` on the alignment candidates. */
export function alignTo3(pts: readonly Vec3[], ref: readonly Vec3[]): Vec3[] {
  const fit = (idx: readonly number[]) =>
    fitSimilarity3(
      idx.map((i) => pts[i]!),
      idx.map((i) => ref[i]!),
    );
  let keep: readonly number[] = ALIGNMENT_CANDIDATES;
  let T = fit(keep);
  for (let it = 0; it < 3; it++) {
    const err = (i: number) => {
      const q = apply3(T, pts[i]!);
      return Math.hypot(q.x - ref[i]!.x, q.y - ref[i]!.y, q.z - ref[i]!.z);
    };
    keep = [...ALIGNMENT_CANDIDATES].sort((a, b) => err(a) - err(b)).slice(0, ALIGNMENT_KEEP);
    T = fit(keep);
  }
  return pts.map((p) => apply3(T, p));
}

/** Turn about the vertical axis (radians) that makes the symmetric pairs level in depth; + = patient left farther. */
export function faceYaw(pts: readonly Vec3[]): number {
  let dx = 0;
  let dz = 0;
  for (const [r, l] of SYMMETRIC_PAIRS) {
    dx += pts[l]!.x - pts[r]!.x;
    dz += pts[l]!.z - pts[r]!.z;
  }
  return dx === 0 ? 0 : Math.atan(dz / dx); // the smallest turn, whichever way the pairs run in x
}

const rotateY = (p: Vec3, c: Vec3, a: number): Vec3 => {
  const x = p.x - c.x;
  const z = p.z - c.z;
  return { x: c.x + x * Math.cos(a) + z * Math.sin(a), y: p.y, z: c.z - x * Math.sin(a) + z * Math.cos(a) };
};

const toObs = (like: FrameObservation, ref: FrameObservation, pts: readonly Vec3[]): FrameObservation => ({
  ...like,
  width: ref.width,
  height: ref.height,
  landmarks: pts.flatMap((p) => [p.x / ref.width, p.y / ref.height, p.z / ref.width]),
});

const hasFace = (o: FrameObservation): boolean => o.landmarks.length >= 468 * 3;

/**
 * Rest and frames in the rest's frame, the rest turned square to the camera. Frames without a face pass unchanged.
 * `yaw` = the rest's turn that was taken out, degrees.
 */
export function frontalizeSet(
  rest: FrameObservation,
  frames: readonly FrameObservation[],
): { rest: FrameObservation; frames: FrameObservation[]; yaw: number } {
  if (!hasFace(rest)) return { rest, frames: [...frames], yaw: 0 };
  const R3 = to3d(rest);
  const a = faceYaw(R3);
  const c = centroid3(ALIGNMENT_CANDIDATES.map((i) => R3[i]!));
  const turn = (ps: readonly Vec3[]) => ps.map((p) => rotateY(p, c, a));
  return {
    rest: toObs(rest, rest, turn(R3)),
    frames: frames.map((f) => (hasFace(f) ? toObs(f, rest, turn(alignTo3(to3d(f), R3))) : f)),
    yaw: (a * 180) / Math.PI,
  };
}
