/**
 * Keeping the app and its records safe: install to the home screen, ask the browser to keep storage, and back up.
 * Home shows at most one short card; Settings shows the full status.
 */
import { useEffect, useState } from 'preact/hooks';
import {
  BACKUP_REMIND,
  backupDue,
  backupSnoozed,
  lastExport,
  markExported,
  requestPersist,
  snoozeBackup,
  storageStatus,
  type StorageStatus,
} from '../../data/backup';
import { download, exportJson } from '../../data/export';
import { getState, useApp } from '../../data/store';
import { Icon } from '../icons';
import { fmtDate } from '../labels';
import { useInstall } from '../install';
import { Notice } from './common';

const INSTALL_DISMISS_KEY = 'fpc.installDismissed.v1';

/** Downloads the full JSON export (the backup import can restore) and remembers when. */
export function backupNow(): void {
  download(`facial-palsy-${new Date().toISOString().slice(0, 10)}.json`, exportJson(getState()), 'application/json');
  markExported();
}

function InstallSteps({ ios }: { ios: boolean }) {
  return ios ? (
    <span>Safari 아래쪽 공유 버튼(네모에 위쪽 화살표) → ‘홈 화면에 추가’를 누르세요.</span>
  ) : (
    <span>브라우저 메뉴(⋮) → ‘홈 화면에 추가’ 또는 ‘앱 설치’를 누르세요.</span>
  );
}

/** Home: one reminder at most — install first (protects storage), then backup. Not for example profiles. */
export function HomeKeepSafe() {
  const { profile, sessions } = useApp();
  const inst = useInstall();
  const [hidden, setHidden] = useState(() => {
    try {
      return localStorage.getItem(INSTALL_DISMISS_KEY) === '1';
    } catch {
      return false;
    }
  });
  const [, rerender] = useState(0);
  if (!profile || profile.demo || profile.demoCaseId) return null;
  if (!inst.installed && !hidden && sessions.length >= 1) {
    return (
      <div class="card tight">
        <div class="row between" style={{ alignItems: 'flex-start' }}>
          <b class="small">홈 화면에 앱으로 설치하세요</b>
          <button
            class="btn sm ghost"
            aria-label="닫기"
            onClick={() => {
              try {
                localStorage.setItem(INSTALL_DISMISS_KEY, '1');
              } catch {
                /* private mode */
              }
              setHidden(true);
            }}
          >
            닫기
          </button>
        </div>
        <p class="xsmall ink2" style={{ margin: '2px 0 6px' }}>
          전체 화면으로 바로 열리고, 브라우저 정리로 기록이 지워질 위험이 줄어듭니다.
        </p>
        {inst.canPrompt ? (
          <button class="btn primary block" onClick={() => void inst.prompt()}>
            <Icon name="download" /> 앱 설치
          </button>
        ) : (
          <div class="xsmall">
            <InstallSteps ios={inst.ios} />
          </div>
        )}
      </div>
    );
  }
  if (backupDue(sessions.length, lastExport(), backupSnoozed())) {
    const last = lastExport();
    return (
      <div class="card tight">
        <b class="small">기록을 백업할 때입니다</b>
        <p class="xsmall ink2" style={{ margin: '2px 0 6px' }}>
          기록은 이 폰에만 있습니다({last ? `마지막 백업 ${fmtDate(last)}` : '아직 백업 없음'}). 파일을 받아 두면 폰을 바꾸거나 기록이
          지워져도 설정 → ‘기록 가져오기’로 되살릴 수 있습니다. 사진은 들어가지 않습니다.
        </p>
        <div class="row">
          <button
            class="btn primary grow"
            onClick={() => {
              backupNow();
              rerender((x) => x + 1);
            }}
          >
            <Icon name="download" /> 지금 백업 파일 받기
          </button>
          <button
            class="btn"
            onClick={() => {
              snoozeBackup();
              rerender((x) => x + 1);
            }}
          >
            {BACKUP_REMIND.snoozeDays}일 뒤에
          </button>
        </div>
      </div>
    );
  }
  return null;
}

/** Settings: install state, storage protection and the last backup. */
export function DeviceCare() {
  const inst = useInstall();
  const [st, setSt] = useState<StorageStatus | null>(null);
  const [asked, setAsked] = useState<boolean | null | undefined>(undefined);
  useEffect(() => {
    storageStatus().then(setSt, () => setSt({ persisted: null, usageMb: null }));
  }, [asked]);
  const last = lastExport();
  return (
    <div class="card">
      <div class="small">
        <b>앱 설치</b>: {inst.installed ? '설치된 앱으로 열려 있습니다.' : '브라우저로 열려 있습니다.'}
      </div>
      {!inst.installed &&
        (inst.canPrompt ? (
          <button class="btn sm block" style={{ marginTop: '6px' }} onClick={() => void inst.prompt()}>
            <Icon name="download" /> 홈 화면에 앱 설치
          </button>
        ) : (
          <div class="xsmall ink2" style={{ marginTop: '4px' }}>
            <InstallSteps ios={inst.ios} />
          </div>
        ))}
      <div class="small" style={{ marginTop: '10px' }}>
        <b>저장 공간 보호</b>:{' '}
        {st === null
          ? '확인 중…'
          : st.persisted
            ? '허용됨 — 공간이 부족해도 브라우저가 기록을 지우지 않습니다.'
            : st.persisted === false
              ? '허용되지 않음 — 공간이 부족하면 브라우저가 지울 수 있습니다.'
              : '이 브라우저는 알려 주지 않습니다.'}
        {st?.usageMb != null && <span class="xsmall muted"> (사용 {st.usageMb} MB)</span>}
      </div>
      {st && !st.persisted && (
        <>
          <button
            class="btn sm block"
            style={{ marginTop: '6px' }}
            onClick={async () => {
              setAsked(await requestPersist());
            }}
          >
            <Icon name="shield" /> 저장 공간 보호 요청
          </button>
          {asked === false && (
            <Notice tone="warn">
              <span class="xsmall">브라우저가 거절했습니다. 앱으로 설치하면 보통 허용됩니다. 그동안은 백업 파일을 받아 두세요.</span>
            </Notice>
          )}
        </>
      )}
      <div class="small" style={{ marginTop: '10px' }}>
        <b>마지막 백업</b>: {last ? fmtDate(last) : '없음'}{' '}
        <span class="xsmall muted">— 아래 ‘전체 기록 내보내기(JSON)’가 백업 파일입니다.</span>
      </div>
    </div>
  );
}
