/**
 * Personal dose from how the last sessions of an exercise felt (쉬움·적당·힘듦·불편). Only volume changes — hold
 * time for stretches, repetitions for movement exercises — by 20 % per step within ±40 % of the prescribed dose;
 * effort never goes up ("최대 힘으로 하지 마세요" stays), and nothing increases in the acute phase.
 */
import type { RehabLog } from '../data/types';
import type { Exercise, Phase } from './exercises';
import { isExpressionExercise, programFor } from './motion';

export const DOSE_VERSION = 'RD-0.1.0';

export type Feel = NonNullable<RehabLog['feel']>;

export const FEEL_LABEL: Record<Feel, string> = {
  easy: '쉬움',
  ok: '적당',
  hard: '힘듦',
  sore: '불편(아픔·당김)',
};

/** Steps below/above the prescribed dose; one step = 20 % of it. */
export const DOSE_STEPS = { min: -2, max: 2, size: 0.2 } as const;

export interface Dose {
  /** Step used for this session (store it on the log). */
  step: number;
  /** Overrides for planFor; empty at the prescribed dose or for timer-only exercises. */
  opts: { holdSec?: number; reps?: number };
  /** Why the dose differs from the prescription, in one sentence (null when it does not). */
  reason: string | null;
  /** Shown after discomfort. */
  caution: string | null;
}

type Unit = { key: 'holdSec' | 'reps'; base: number; min: number; label: (n: number) => string };

/** What a step changes: hold seconds for stretches, repetitions for movement exercises; timers do not change. */
function unitOf(ex: Exercise): Unit | null {
  if (programFor(ex.id)) return { key: 'holdSec', base: ex.holdSec ?? 10, min: 3, label: (n) => `유지 ${n}초` };
  if (isExpressionExercise(ex.id)) return { key: 'reps', base: ex.reps ?? 5, min: 2, label: (n) => `${n}회` };
  return null;
}

/** Dose for the next session of `ex` from its earlier logs (any order). */
export function doseFor(ex: Exercise, logs: readonly RehabLog[], phase: Phase): Dose {
  const unit = unitOf(ex);
  const mine = logs.filter((l) => l.exerciseId === ex.id).sort((a, b) => a.at.localeCompare(b.at));
  const last = mine[mine.length - 1];
  const was = last?.doseStep ?? 0;
  const felt = mine.filter((l) => l.feel);
  let step = was;
  let why: string | null = null;
  let caution: string | null = null;
  // Only an answer given for the latest session moves the dose, so one answer counts once.
  if (last?.feel === 'sore') {
    step -= 1;
    why = '지난번 ‘불편’';
    caution =
      felt[felt.length - 2]?.feel === 'sore'
        ? '두 번 연속 불편하다고 기록했습니다. 이 운동은 쉬고, 계속 아프거나 당기면 의료진과 상의하세요.'
        : '지난번 불편했다고 기록해 양을 줄였습니다. 아프거나 당기면 바로 멈추세요.';
  } else if (last?.feel === 'hard') {
    step -= 1;
    why = '지난번 ‘힘듦’';
  } else if (last?.feel === 'easy' && phase !== 'acute') {
    // Up only after two 'easy' answers at the current dose.
    const atStep = felt.filter((l) => (l.doseStep ?? 0) === was);
    if (atStep.length >= 2 && atStep.slice(-2).every((l) => l.feel === 'easy')) {
      step += 1;
      why = '두 번 연속 ‘쉬움’';
    }
  }
  if (phase === 'acute') step = Math.min(0, step);
  step = unit ? Math.max(DOSE_STEPS.min, Math.min(DOSE_STEPS.max, step)) : 0;
  if (!unit || step === 0)
    return { step, opts: {}, reason: why && unit ? `${why} — 처방한 양(${unit.label(unit.base)})으로 돌아왔습니다.` : null, caution };
  const n = Math.max(unit.min, Math.round(unit.base * (1 + DOSE_STEPS.size * step)));
  if (why && step === was)
    return {
      step,
      opts: { [unit.key]: n },
      reason: `${why}: 이미 가장 ${step < 0 ? '적은' : '많은'} 양(${unit.label(n)})입니다.`,
      caution,
    };
  return {
    step,
    opts: { [unit.key]: n },
    reason: `${why ?? '지난 기록'}에 맞춰 ${unit.label(n)}로 ${step > 0 ? '늘렸습니다' : '줄였습니다'}(처방 ${unit.label(unit.base)}).`,
    caution,
  };
}
