/**
 * Cuts a recognised frame sequence (FPA-EXPR per frame) into movement segments and picks the held frames of each,
 * so an uploaded video can be analysed like the guided assessment. Pure and deterministic.
 */
import type { ExpressionLabel } from './expression';
import { AGGREGATION } from './analyze';

export interface FrameGuess {
  t: number;
  /** Null when the frame has no face. */
  label: ExpressionLabel | null;
  /** Model probability of `label` (1 for rule-based labels). */
  prob: number;
  /** Movement strength per label (ExpressionGuess.strength): ranks the frames of a segment. */
  strength: Record<ExpressionLabel, number>;
}

export interface Segment {
  label: ExpressionLabel | null;
  start: number;
  end: number;
  peakT: number;
  /** Frame indices used for the analysis: the held part of a movement, the calmest frames of a rest segment. */
  held: number[];
}

export const SEGMENTS = Object.freeze({
  /** Label smoothing: majority over ±halfWindow frames. */
  halfWindow: 2,
  /** Shorter runs are merged into the previous run. */
  minFrames: 3,
  heldRelative: AGGREGATION.peakRelative,
  maxHeld: AGGREGATION.maxPeakFrames,
  /** A short hold still yields the video analysis minimum: the strongest frames of the segment fill up to this. */
  minHeld: AGGREGATION.minValidFrames.video,
  maxRest: 12,
  /**
   * A frame counts as a movement only with at least this probability; below it, it is 'other' (talking, in between).
   * Pucker needs more: speech rounds the lips every few frames and the model learned pucker from rendered faces only.
   * Tuned on the Kozielski video (tools/eval, docs/04 §13): all its brow / eye-closure / wink / smile passages and
   * none of its talking.
   */
  minProb: 0.45,
  minProbPucker: 0.7,
});

function smooth(labels: (ExpressionLabel | null)[], hw: number): (ExpressionLabel | null)[] {
  return labels.map((l, i) => {
    const count = new Map<ExpressionLabel | null, number>();
    for (let j = Math.max(0, i - hw); j <= Math.min(labels.length - 1, i + hw); j++)
      count.set(labels[j]!, (count.get(labels[j]!) ?? 0) + 1);
    let best = l;
    let n = count.get(l) ?? 0;
    for (const [k, c] of count) if (c > n) [best, n] = [k, c];
    return best;
  });
}

export function segmentFrames(fr: readonly FrameGuess[], opts: Partial<typeof SEGMENTS> = {}): Segment[] {
  const o = { ...SEGMENTS, ...opts };
  if (fr.length === 0) return [];
  const firm = fr.map((f) =>
    f.label === null || f.label === 'rest' || f.label === 'other' || f.prob >= (f.label === 'pucker' ? o.minProbPucker : o.minProb)
      ? f.label
      : ('other' as const),
  );
  const lab = smooth(firm, o.halfWindow);
  // Runs of equal labels.
  const runs: { label: ExpressionLabel | null; from: number; to: number }[] = [];
  lab.forEach((l, i) => {
    const last = runs[runs.length - 1];
    if (last && last.label === l) last.to = i;
    else runs.push({ label: l, from: i, to: i });
  });
  // Short runs join the previous run (or the next one at the start); neighbours with the same label merge.
  const merged: typeof runs = [];
  for (const r of runs) {
    const last = merged[merged.length - 1];
    if (last && (r.to - r.from + 1 < o.minFrames || last.label === r.label)) last.to = r.to;
    else merged.push({ ...r });
  }
  if (merged.length > 1 && merged[0]!.to - merged[0]!.from + 1 < o.minFrames) {
    merged[1]!.from = merged[0]!.from;
    merged.shift();
  }
  return merged.map((r) => {
    const idx = Array.from({ length: r.to - r.from + 1 }, (_, k) => r.from + k).filter((i) => fr[i]!.label !== null);
    const strength = (i: number) => (r.label === null ? 0 : (fr[i]!.strength[r.label] ?? 0));
    let held: number[] = [];
    let peak = idx[0] ?? r.from;
    if (idx.length && r.label !== null && r.label !== 'other') {
      peak = idx.reduce((b, i) => (strength(i) > strength(b) ? i : b), idx[0]!);
      const cut = r.label === 'rest' ? 0 : o.heldRelative * strength(peak);
      const byStrength = [...idx].sort((a, b) => strength(b) - strength(a));
      const over = byStrength.filter((i) => strength(i) >= cut).length;
      held = byStrength.slice(0, Math.min(Math.max(over, o.minHeld), r.label === 'rest' ? o.maxRest : o.maxHeld)).sort((a, b) => a - b);
    }
    return { label: r.label, start: fr[r.from]!.t, end: fr[r.to]!.t, peakT: fr[peak]!.t, held };
  });
}
