/** 3×3 unlock pattern: drag through the dots (a skipped-over middle dot is added, as on Android phones). */
import { useRef, useState } from 'preact/hooks';

const SIZE = 240;
const STEP = 80;
const R_HIT = 30;
const pos = (i: number) => ({ x: 40 + (i % 3) * STEP, y: 40 + Math.floor(i / 3) * STEP });

/** The dot between two dots on a line (row, column or diagonal), if any. */
export function between(a: number, b: number): number | null {
  const [ra, ca, rb, cb] = [Math.floor(a / 3), a % 3, Math.floor(b / 3), b % 3];
  if ((ra + rb) % 2 || (ca + cb) % 2) return null;
  const m = ((ra + rb) / 2) * 3 + (ca + cb) / 2;
  return m === a || m === b ? null : m;
}

export function PatternPad({
  onDone,
  disabled = false,
  error = false,
}: {
  onDone: (dots: number[]) => void;
  disabled?: boolean;
  error?: boolean;
}) {
  const [dots, setDots] = useState<number[]>([]);
  const [tip, setTip] = useState<{ x: number; y: number } | null>(null);
  const svg = useRef<SVGSVGElement>(null);
  const drawing = useRef(false);

  const point = (e: PointerEvent) => {
    const r = svg.current!.getBoundingClientRect();
    return { x: ((e.clientX - r.left) / r.width) * SIZE, y: ((e.clientY - r.top) / r.height) * SIZE };
  };
  const hit = (p: { x: number; y: number }) => {
    for (let i = 0; i < 9; i++) {
      const d = pos(i);
      if (Math.hypot(d.x - p.x, d.y - p.y) <= R_HIT) return i;
    }
    return null;
  };
  const add = (list: number[], i: number) => {
    if (list.includes(i)) return list;
    const last = list[list.length - 1];
    const mid = last === undefined ? null : between(last, i);
    return mid !== null && !list.includes(mid) ? [...list, mid, i] : [...list, i];
  };

  return (
    <svg
      ref={svg}
      viewBox={`0 0 ${SIZE} ${SIZE}`}
      class="pattern-pad"
      role="img"
      aria-label="패턴 입력: 점 네 개 이상을 이어 그리세요"
      style={{ touchAction: 'none', opacity: disabled ? 0.4 : 1 }}
      onPointerDown={(e) => {
        if (disabled) return;
        (e.currentTarget as SVGSVGElement).setPointerCapture(e.pointerId);
        drawing.current = true;
        const p = point(e);
        const i = hit(p);
        setDots(i === null ? [] : [i]);
        setTip(p);
      }}
      onPointerMove={(e) => {
        if (!drawing.current) return;
        const p = point(e);
        setTip(p);
        const i = hit(p);
        if (i !== null) setDots((d) => add(d, i));
      }}
      onPointerUp={() => {
        if (!drawing.current) return;
        drawing.current = false;
        setTip(null);
        const done = dots;
        setDots([]);
        if (done.length) onDone(done);
      }}
      onPointerCancel={() => {
        drawing.current = false;
        setTip(null);
        setDots([]);
      }}
    >
      {dots.length > 1 && (
        <polyline
          points={dots.map((i) => `${pos(i).x},${pos(i).y}`).join(' ')}
          fill="none"
          stroke={error ? 'var(--critical)' : 'var(--accent)'}
          stroke-width="6"
          stroke-linecap="round"
          stroke-linejoin="round"
        />
      )}
      {tip && dots.length > 0 && (
        <line
          x1={pos(dots[dots.length - 1]!).x}
          y1={pos(dots[dots.length - 1]!).y}
          x2={tip.x}
          y2={tip.y}
          stroke="var(--accent)"
          stroke-width="4"
          stroke-linecap="round"
          opacity="0.5"
        />
      )}
      {Array.from({ length: 9 }, (_, i) => (
        <circle
          cx={pos(i).x}
          cy={pos(i).y}
          r={dots.includes(i) ? 13 : 9}
          fill={dots.includes(i) ? 'var(--accent)' : 'var(--ink-2, #666)'}
        />
      ))}
    </svg>
  );
}
