/** Settings → 앱 잠금: register several ways to open the app (password, pattern, fingerprint/face) and turn the lock on. */
import { useEffect, useState } from 'preact/hooks';
import {
  MIN_METHODS,
  PASSWORD_MIN,
  PATTERN_MIN_DOTS,
  biometricAvailable,
  hashSecret,
  loadLock,
  newRecoveryCode,
  patternKey,
  registerBiometric,
  registered,
  saveLock,
  validPattern,
  type LockConfig,
  type LockMethod,
} from '../../data/lock';
import { Icon } from '../icons';
import { Notice, Segmented } from './common';
import { PatternPad } from './PatternPad';

const NAME: Record<LockMethod, string> = { password: '비밀번호', pattern: '패턴', biometric: '지문·얼굴 인식' };

function PasswordForm({ onSave, onCancel }: { onSave: (pw: string) => void; onCancel: () => void }) {
  const [a, setA] = useState('');
  const [b, setB] = useState('');
  const err =
    a && a.length < PASSWORD_MIN ? `${PASSWORD_MIN}자 이상으로 정해 주세요.` : a && b && a !== b ? '두 번 입력한 내용이 다릅니다.' : null;
  return (
    <div class="stack" style={{ gap: '6px', marginTop: '6px' }}>
      <input
        type="password"
        autoComplete="new-password"
        placeholder={`새 비밀번호(${PASSWORD_MIN}자 이상, 숫자만도 가능)`}
        value={a}
        onInput={(e) => setA((e.target as HTMLInputElement).value)}
      />
      <input
        type="password"
        autoComplete="new-password"
        placeholder="한 번 더 입력"
        value={b}
        onInput={(e) => setB((e.target as HTMLInputElement).value)}
      />
      {err && (
        <span class="xsmall" style={{ color: 'var(--critical)' }}>
          {err}
        </span>
      )}
      <div class="row">
        <button class="btn grow" onClick={onCancel}>
          취소
        </button>
        <button class="btn primary grow" disabled={!a || a !== b || a.length < PASSWORD_MIN} onClick={() => onSave(a)}>
          저장
        </button>
      </div>
    </div>
  );
}

function PatternForm({ onSave, onCancel }: { onSave: (dots: number[]) => void; onCancel: () => void }) {
  const [first, setFirst] = useState<number[] | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <div class="center" style={{ marginTop: '6px' }}>
      <p class="small" style={{ margin: '0 0 4px' }}>
        {first ? '확인을 위해 같은 패턴을 한 번 더 그리세요.' : `점 ${PATTERN_MIN_DOTS}개 이상을 이어 그리세요.`}
      </p>
      <PatternPad
        error={!!msg}
        onDone={(dots) => {
          if (!validPattern(dots)) {
            setMsg(`점 ${PATTERN_MIN_DOTS}개 이상이 필요합니다.`);
            return;
          }
          if (!first) {
            setFirst(dots);
            setMsg(null);
            return;
          }
          if (first.join() !== dots.join()) {
            setFirst(null);
            setMsg('두 패턴이 다릅니다. 처음부터 다시 그리세요.');
            return;
          }
          onSave(dots);
        }}
      />
      {msg && (
        <p class="xsmall" style={{ color: 'var(--critical)', margin: '2px 0' }}>
          {msg}
        </p>
      )}
      <button class="btn sm" onClick={onCancel}>
        취소
      </button>
    </div>
  );
}

export function AppLockSettings() {
  const [cfg, setCfg] = useState<LockConfig>(loadLock);
  const [editing, setEditing] = useState<LockMethod | null>(null);
  const [bioOk, setBioOk] = useState(false);
  const [code, setCode] = useState<string | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  useEffect(() => {
    biometricAvailable().then(setBioOk, () => setBioOk(false));
  }, []);
  const methods = registered(cfg);
  const update = (next: LockConfig) => {
    saveLock(next);
    setCfg(next);
  };

  const remove = (m: LockMethod) => {
    if (cfg.enabled && methods.length <= MIN_METHODS) {
      setMsg(`잠금을 켠 동안에는 여는 방법이 ${MIN_METHODS}가지 이상 있어야 합니다. 다른 방법을 먼저 등록하거나 잠금을 끄세요.`);
      return;
    }
    const next = { ...cfg };
    delete next[m];
    update(next);
  };

  const turnOn = async () => {
    const c = newRecoveryCode();
    update({ ...cfg, enabled: true, recovery: await hashSecret(c) });
    setCode(c);
  };

  return (
    <div class="card">
      <div class="small">
        앱을 열 때 비밀번호·패턴·지문 중 하나를 확인합니다. 하나를 잊어도 다른 방법으로 열 수 있게 <b>{MIN_METHODS}가지 이상</b>을 등록해야
        켤 수 있습니다.
      </div>
      <div class="list" style={{ marginTop: '6px' }}>
        {(['password', 'pattern', 'biometric'] as const).map((m) => (
          <div class="list-item" style={{ display: 'block', cursor: 'default' }}>
            <div class="row between">
              <span class="small">
                {NAME[m]} {cfg[m] ? <span class="chip good">등록됨</span> : <span class="xsmall muted">등록 안 됨</span>}
              </span>
              <span class="row" style={{ gap: '6px' }}>
                {m === 'biometric' ? (
                  cfg.biometric ? (
                    <button class="btn sm ghost" onClick={() => remove(m)}>
                      삭제
                    </button>
                  ) : (
                    <button
                      class="btn sm"
                      disabled={!bioOk}
                      onClick={async () => {
                        setMsg(null);
                        try {
                          update({ ...cfg, biometric: await registerBiometric() });
                        } catch {
                          setMsg('지문·얼굴 등록이 취소되었거나 실패했습니다.');
                        }
                      }}
                    >
                      등록
                    </button>
                  )
                ) : (
                  <>
                    <button class="btn sm" onClick={() => setEditing(editing === m ? null : m)}>
                      {cfg[m] ? '변경' : '등록'}
                    </button>
                    {cfg[m] && (
                      <button class="btn sm ghost" onClick={() => remove(m)}>
                        삭제
                      </button>
                    )}
                  </>
                )}
              </span>
            </div>
            {m === 'biometric' && !bioOk && !cfg.biometric && (
              <div class="xsmall muted">이 기기·브라우저에서는 지문·얼굴 인식을 쓸 수 없습니다.</div>
            )}
            {editing === 'password' && m === 'password' && (
              <PasswordForm
                onCancel={() => setEditing(null)}
                onSave={async (pw) => {
                  update({ ...loadLock(), password: await hashSecret(pw) });
                  setEditing(null);
                }}
              />
            )}
            {editing === 'pattern' && m === 'pattern' && (
              <PatternForm
                onCancel={() => setEditing(null)}
                onSave={async (dots) => {
                  update({ ...loadLock(), pattern: await hashSecret(patternKey(dots)) });
                  setEditing(null);
                }}
              />
            )}
          </div>
        ))}
      </div>

      {msg && (
        <Notice tone="warn">
          <span class="small">{msg}</span>
        </Notice>
      )}

      {code && (
        <div class="card warn" style={{ margin: '8px 0 0' }}>
          <b class="small">복구 코드 — 지금 적어 두세요(다시 보여 드리지 않습니다)</b>
          <div class="mono" style={{ fontSize: '20px', letterSpacing: '1px', margin: '6px 0', userSelect: 'all' }}>
            {code}
          </div>
          <p class="xsmall ink2" style={{ margin: 0 }}>
            등록한 방법을 모두 잊었을 때 이 코드로 열 수 있습니다. 종이에 적거나 다른 곳에 안전하게 보관하세요.
          </p>
          <button class="btn sm block" style={{ marginTop: '6px' }} onClick={() => setCode(null)}>
            적어 두었어요
          </button>
        </div>
      )}

      <div style={{ marginTop: '10px' }}>
        {cfg.enabled ? (
          <>
            <div class="small">
              <Icon name="shield" /> 앱 잠금 <b>켜짐</b> · 여는 방법 {methods.map((m) => NAME[m]).join(', ')} + 복구 코드
            </div>
            <div class="field" style={{ marginTop: '6px' }}>
              <span>다시 잠그기</span>
              <Segmented
                label="다시 잠그기"
                value={String(cfg.relockMin)}
                onChange={(v) => update({ ...cfg, relockMin: Number(v) })}
                options={[
                  { value: '0', label: '나가면 바로' },
                  { value: '1', label: '1분 뒤' },
                  { value: '5', label: '5분 뒤' },
                ]}
              />
            </div>
            <div class="row" style={{ marginTop: '6px' }}>
              <button class="btn sm grow" onClick={turnOn}>
                복구 코드 새로 만들기
              </button>
              <button
                class="btn sm grow"
                onClick={() => {
                  if (!confirm('앱 잠금을 끕니다. 등록한 방법은 남아 있어 다시 켤 수 있습니다.')) return;
                  update({ ...cfg, enabled: false });
                }}
              >
                잠금 끄기
              </button>
            </div>
          </>
        ) : (
          <button class="btn primary block" disabled={methods.length < MIN_METHODS} onClick={turnOn}>
            <Icon name="shield" /> 앱 잠금 켜기 {methods.length < MIN_METHODS ? `(${MIN_METHODS - methods.length}가지 더 등록 필요)` : ''}
          </button>
        )}
      </div>
      <p class="xsmall muted" style={{ margin: '6px 0 0' }}>
        비밀번호·패턴은 이 기기에 암호화된 해시로만 저장되고, 지문·얼굴 정보는 폰 밖으로 나오지 않습니다(폰의 잠금 기능이 확인). 앱 잠금은
        화면을 가리는 기능이라, 폰 자체의 화면 잠금도 함께 켜 두세요.
      </p>
    </div>
  );
}
