/** Institution PIN step before clinician or researcher mode (data/mode.ts): made once on the device, then asked. */
import { useState } from 'preact/hooks';
import { MODE_PIN, checkModePin, hasModePin, modePinWaitMs, setModePin } from '../../data/mode';
import { Notice } from './common';

const digits = (e: Event): string => (e.target as HTMLInputElement).value.replace(/\D/g, '').slice(0, 8);

/** `make` forces a new PIN (changing it from clinician mode); otherwise a PIN is made only if the device has none. */
export function ModePinForm({
  label,
  make: forceMake = false,
  onOk,
  onCancel,
}: {
  label: string;
  make?: boolean;
  onOk: () => void | Promise<void>;
  onCancel: () => void;
}) {
  const [make] = useState(() => forceMake || !hasModePin());
  const [pin, setPin] = useState('');
  const [again, setAgain] = useState('');
  const [msg, setMsg] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async (e: Event) => {
    e.preventDefault();
    setMsg(null);
    if (make) {
      if (!MODE_PIN.test(pin)) return setMsg('숫자 4~8자리로 정해 주세요.');
      if (pin !== again) return setMsg('두 번 입력한 PIN이 다릅니다.');
    }
    setBusy(true);
    try {
      if (make) {
        await setModePin(pin);
        return await onOk();
      }
      const r = await checkModePin(pin);
      if (r === 'ok') return await onOk();
      setPin('');
      const wait = modePinWaitMs();
      setMsg(wait > 0 ? `잘못 입력한 횟수가 많아 ${Math.ceil(wait / 1000)}초 뒤에 다시 할 수 있습니다.` : 'PIN이 맞지 않습니다.');
    } finally {
      setBusy(false);
    }
  };

  return (
    <form class="stack" style={{ gap: '10px' }} onSubmit={submit}>
      <Notice>
        <span class="small">
          {forceMake
            ? '새 기관 PIN을 정하세요(숫자 4~8자리). 환자 모드에서 의료진·연구자 모드로 바꿀 때 묻습니다.'
            : make
              ? `${label} 모드로 바꾸려면 이 기기의 기관 PIN을 먼저 만드세요(숫자 4~8자리). 앞으로 환자 모드에서 바꿀 때마다 묻습니다. 병원·연구팀만 알도록 하세요.`
              : `${label} 모드로 바꾸려면 기관 PIN을 입력하세요.`}
        </span>
      </Notice>
      <label class="field">
        <span>{make ? '새 PIN' : 'PIN'}</span>
        <input
          class="input"
          type="password"
          inputMode="numeric"
          autocomplete="off"
          maxLength={8}
          value={pin}
          onInput={(e) => setPin(digits(e))}
          aria-label={make ? '새 기관 PIN' : '기관 PIN'}
        />
      </label>
      {make && (
        <label class="field">
          <span>한 번 더</span>
          <input
            class="input"
            type="password"
            inputMode="numeric"
            autocomplete="off"
            maxLength={8}
            value={again}
            onInput={(e) => setAgain(digits(e))}
            aria-label="기관 PIN 한 번 더"
          />
        </label>
      )}
      {msg && (
        <Notice tone="danger">
          <span class="small">{msg}</span>
        </Notice>
      )}
      <div class="row">
        <button type="button" class="btn grow" onClick={onCancel}>
          취소
        </button>
        <button type="submit" class="btn primary grow" disabled={busy || pin.length < 4}>
          {forceMake ? 'PIN 바꾸기' : make ? 'PIN 만들고 바꾸기' : '확인'}
        </button>
      </div>
      {!make && (
        <span class="xsmall muted">
          PIN을 잊었으면 기기를 관리하는 연구팀에 문의하세요. 연구 피험자가 없는 기기에서는 ‘모든 데이터 삭제’를 하면 모드와 PIN도 함께
          지워집니다.
        </span>
      )}
    </form>
  );
}
