/**
 * Who is using the app on this device (data/mode.ts; older installs: profile.role): the same build shows a patient, a
 * clinician or a researcher what each needs. Features that change the intended use stay in config.ts (build
 * profiles); the role only chooses what is shown within them. Leaving patient mode asks for the institution PIN.
 *  patient    – movement %, rehab, upload; estimated clinical scales hidden unless asked for (profile.showScales)
 *  clinician  – + estimated HB/Sunnybrook, clinician rating entry, research subjects, agreement statistics
 *  researcher – + development tools (animation review, bench)
 */
import { FEATURES } from '../config';
import { deviceRole } from '../data/mode';
import type { Profile, UserRole } from '../data/types';
import { useApp } from '../data/store';

export const ROLE_LABEL: Record<UserRole, string> = { patient: '환자', clinician: '의료진', researcher: '연구자' };

export const roleOf = (p: Profile | null | undefined): UserRole => deviceRole() ?? p?.role ?? 'patient';

/** Roles this build offers (no clinical scales → patient only; no research tools → no researcher). */
export function availableRoles(): UserRole[] {
  if (!FEATURES.estimatedScales) return ['patient'];
  return FEATURES.researchTools ? ['patient', 'clinician', 'researcher'] : ['patient', 'clinician'];
}

/** Estimated House–Brackmann / Sunnybrook values: always for clinicians and researchers, for patients only on request. */
export const showScales = (p: Profile | null | undefined): boolean =>
  FEATURES.estimatedScales && (roleOf(p) !== 'patient' || !!p?.showScales);

/** Clinician rating entry, research subjects, agreement statistics. */
export const showClinicalTools = (p: Profile | null | undefined): boolean => FEATURES.researchTools && roleOf(p) !== 'patient';

/** Development tools (animation review, bench, pose lab). */
export const showDevTools = (p: Profile | null | undefined): boolean => FEATURES.researchTools && roleOf(p) === 'researcher';

export function useRole() {
  const { profile } = useApp();
  return { role: roleOf(profile), scales: showScales(profile), clinical: showClinicalTools(profile), dev: showDevTools(profile) };
}
