import { useEffect, useRef, useState } from 'preact/hooks';
import { FEATURES } from '../config';
import { actions, useApp } from '../data/store';
import { loadLock, registered } from '../data/lock';
import { activeSubject } from '../data/subjects';
import { LockScreen } from './components/LockScreen';
import { TabBar } from './components/common';
import { useRoute } from './router';
import { lazyScreen } from './lazy';
import { Home } from './screens/Home';
import { Onboarding } from './screens/Onboarding';
import { Settings } from './screens/Settings';
import { showClinicalTools } from './role';

// Screens outside the first view are code-split.
const Assess = lazyScreen(() => import('./screens/Assess').then((m) => m.Assess));
const SessionDetail = lazyScreen(() => import('./screens/SessionDetail').then((m) => m.SessionDetail));
const Progress = lazyScreen(() => import('./screens/Progress').then((m) => m.Progress));
const Report = lazyScreen(() => import('./screens/Report').then((m) => m.Report));
const Subjects = lazyScreen(() => import('./screens/Subjects').then((m) => m.Subjects));
const Rehab = lazyScreen(() => import('./screens/Rehab').then((m) => m.Rehab));
const ExercisePlayer = lazyScreen(() => import('./screens/Exercise').then((m) => m.ExercisePlayer));
const RoutinePlayer = lazyScreen(() => import('./screens/Exercise').then((m) => m.RoutinePlayer));
const SynkFinder = lazyScreen(() => import('./screens/SynkFinder').then((m) => m.SynkFinder));
const Research = lazyScreen(() => import('./screens/Research').then((m) => m.Research));
const ResearchPackage = lazyScreen(() => import('./screens/ResearchPackage').then((m) => m.ResearchPackage));
const Collect = lazyScreen(() => import('./screens/Collect').then((m) => m.Collect));
const Rate = lazyScreen(() => import('./screens/Rate').then((m) => m.Rate));
const Upload = lazyScreen(() => import('./screens/Upload').then((m) => m.Upload));
const Bench = lazyScreen(() => import('./screens/Bench').then((m) => m.Bench));
const PoseLab = lazyScreen(() => import('./screens/PoseLab').then((m) => m.PoseLab));
const AnimReview = lazyScreen(() => import('./screens/AnimReview').then((m) => m.AnimReview));
const CaseGallery = lazyScreen(() => import('./screens/Cases').then((m) => m.CaseGallery));
const CaseDashboard = lazyScreen(() => import('./screens/Cases').then((m) => m.CaseDashboard));

/** Open research subject (research builds): shown on every screen so records go to the right person. */
const subject = FEATURES.researchTools ? activeSubject() : null;

/** Switching subjects is for clinician mode only (a patient holding the device stays on their own record). */
function SubjectBanner({ code, canSwitch }: { code: string; canSwitch: boolean }) {
  return (
    <div class="demo-banner subject-banner" role="status">
      <span>
        연구 피험자 <b>{code}</b> · 기록은 이 피험자에게만 저장됩니다
      </span>
      {canSwitch && (
        <a class="btn sm" href="#/subjects">
          전환
        </a>
      )}
    </div>
  );
}

/** Locked when the app lock is on (settings → 앱 잠금), at start and after the set time in the background. */
function useAppLock(): [boolean, () => void] {
  const on = () => {
    const c = loadLock();
    return c.enabled && registered(c).length > 0;
  };
  const [locked, setLocked] = useState(on);
  const state = useRef({ locked: on(), unlockedAt: 0, hiddenAt: 0 });
  useEffect(() => {
    const vis = () => {
      const st = state.current;
      // The lock screen itself (and the phone's fingerprint sheet) may hide the page: only count time away while open.
      if (!on() || st.locked) return;
      if (document.visibilityState === 'hidden') {
        if (Date.now() - st.unlockedAt > 3000) st.hiddenAt = Date.now();
      } else if (st.hiddenAt && Date.now() - st.hiddenAt >= loadLock().relockMin * 60_000) {
        st.locked = true;
        st.hiddenAt = 0;
        setLocked(true);
      } else st.hiddenAt = 0;
    };
    document.addEventListener('visibilitychange', vis);
    return () => document.removeEventListener('visibilitychange', vis);
  }, []);
  return [
    locked,
    () => {
      state.current = { locked: false, unlockedAt: Date.now(), hiddenAt: 0 };
      setLocked(false);
    },
  ];
}

export function App() {
  const app = useApp();
  const [root, arg] = useRoute();
  const [locked, unlock] = useAppLock();
  useEffect(() => {
    actions.init().catch((e) => console.error('init failed', e));
  }, []);

  if (locked) return <LockScreen onUnlock={unlock} />;

  if (!app.ready) return <div class="splash">불러오는 중…</div>;
  // A clinic device set up in clinician mode can start from research subject codes without a record of its own.
  if (!app.profile && root === 'subjects' && FEATURES.researchTools && showClinicalTools(null))
    return (
      <div class="shell">
        <Subjects />
      </div>
    );
  // The research PC opens the collection screen without a record of its own (it keeps nothing; packages need the password).
  if (!app.profile && root === 'collect' && FEATURES.researchTools)
    return (
      <div class="shell">
        <Collect />
      </div>
    );
  if (!app.profile)
    return (
      <div class="shell">
        {subject && <SubjectBanner code={subject} canSwitch={showClinicalTools(app.profile)} />}
        <Onboarding subject={subject} />
      </div>
    );

  let screen;
  let tab: string | null = null;
  const blocked =
    (!FEATURES.researchTools &&
      (root === 'research' ||
        root === 'package' ||
        root === 'collect' ||
        root === 'rate' ||
        root === 'anim-review' ||
        root === 'pose-lab' ||
        root === 'subjects')) ||
    (FEATURES.rehab === 'off' && (root === 'rehab' || root === 'exercise' || root === 'routine')) ||
    (!FEATURES.demo && (root === 'cases' || root === 'case')) ||
    // Clinician ratings, other subjects and agreement data stay closed in patient mode (the PIN guards leaving it).
    (!showClinicalTools(app.profile) && (root === 'rate' || root === 'subjects' || root === 'research' || root === 'collect'));
  switch (blocked ? undefined : root) {
    case undefined:
      screen = <Home />;
      tab = '/';
      break;
    case 'assess':
      screen = <Assess />;
      break;
    case 'synk':
      screen = <SynkFinder key={arg ?? 'new'} id={arg} />;
      break;
    case 'session':
      screen = <SessionDetail id={arg ?? ''} />;
      break;
    case 'report':
      screen = <Report />;
      break;
    case 'subjects':
      screen = <Subjects />;
      break;
    case 'progress':
      screen = <Progress />;
      tab = '/progress';
      break;
    case 'rehab':
      screen = <Rehab />;
      tab = '/rehab';
      break;
    case 'exercise':
      screen = <ExercisePlayer key={arg} id={arg ?? ''} />;
      break;
    case 'routine':
      screen = <RoutinePlayer key={arg} index={Number(arg) || 0} />;
      break;
    case 'settings':
      screen = <Settings />;
      tab = '/settings';
      break;
    case 'research':
      screen = <Research />;
      break;
    case 'package':
      screen = <ResearchPackage />;
      break;
    case 'collect':
      screen = <Collect />;
      break;
    case 'rate':
      screen = <Rate id={arg ?? ''} />;
      break;
    case 'upload':
    case 'photo':
      screen = <Upload />;
      break;
    case 'pose-lab':
      screen = <PoseLab />;
      break;
    case 'bench':
      screen = import.meta.env.DEV ? <Bench /> : <Home />;
      break;
    case 'anim-review':
      screen = <AnimReview />;
      break;
    case 'cases':
      screen = <CaseGallery />;
      break;
    case 'case':
      screen = <CaseDashboard id={arg ?? ''} />;
      break;
    default:
      screen = <Home />;
      tab = '/';
  }
  return (
    <div class="shell">
      {subject && <SubjectBanner code={subject} canSwitch={showClinicalTools(app.profile)} />}
      {(app.profile.demo || app.profile.demoCaseId) && <DemoBanner />}
      {screen}
      {tab && <TabBar active={tab} />}
    </div>
  );
}

/** Shown on every screen while an example profile is loaded, so demo results are never taken for one's own. */
function DemoBanner() {
  return (
    <div class="demo-banner" role="status">
      <span>
        <b>체험 중</b> · 예시 기록이며 내 결과가 아닙니다
      </span>
      <button
        class="btn sm"
        onClick={async () => {
          if (!confirm('예시(데모) 기록을 모두 지우고 내 정보로 새로 시작합니다. 계속할까요?')) return;
          await actions.deleteAll();
          location.hash = '/';
        }}
      >
        내 프로필로 시작
      </button>
    </div>
  );
}
